SELECT (DATE_TRUNC('DAY', "METERING_HOUR")) AS "TIME_BUCKET", SUM(CREDITS_CLOUD_SERVICES) AS "ORG_CLOUD_SERVICES_CREDITS_BY_ACCOUNT" FROM (SELECT "ACCOUNT_NAME" AS ACCOUNT_NAME, "ORGANIZATION_NAME" AS ORGANIZATION_NAME, "ACCOUNT_LOCATOR" AS ACCOUNT_LOCATOR, "REGION" AS REGION, "WAREHOUSE_ID" AS WAREHOUSE_ID, "WAREHOUSE_NAME" AS WAREHOUSE_NAME, (DATE_TRUNC('HOUR', (TRY_CAST("START_TIME" AS TIMESTAMP)))) AS METERING_HOUR, (CAST("CREDITS_USED" AS DECIMAL(38, 9))) AS CREDITS_USED, (CAST("CREDITS_USED_COMPUTE" AS DECIMAL(38, 9))) AS CREDITS_COMPUTE, (CAST("CREDITS_USED_CLOUD_SERVICES" AS DECIMAL(38, 9))) AS CREDITS_CLOUD_SERVICES FROM org_warehouse_metering_history) AS base GROUP BY (DATE_TRUNC('DAY', "METERING_HOUR")) ORDER BY "ORG_CLOUD_SERVICES_CREDITS_BY_ACCOUNT" DESC, "TIME_BUCKET" LIMIT 100
